#include <stdio.h>
void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }
int main(void) {
    int x = 10, y = 20;
    int *p = &x;
    printf("x=%d *p=%d\n", x, *p);
    *p = 15;
    swap(&x, &y);
    printf("x=%d y=%d\n", x, y);
    return 0;
}

#include <stdio.h>
void set_null(int **pp) { *pp = NULL; }
int main(void) {
    int a[4] = {5, 10, 15, 20};
    int *p = a;
    printf("%d %d %d\n", *p, *(p + 2), (int)((p + 3) - p));
    for (int *q = a; q < a + 4; q++) printf("%d ", *q);
    printf("\n");
    int *n = a;
    set_null(&n);
    printf("%s\n", n == NULL ? "null" : "not null");
    return 0;
}

