#include <stdio.h>

int main(void) {
    int x = 5;
    int *p = &x;
    printf("addr_ok=%s value=%d\n", (void *)p == (void *)&x ? "yes" : "no", *p);
    *p = 99;
    printf("value=%d\n", x);
    int a[3] = {10, 20, 30};
    for (int i = 0; i < 3; i++) printf("%d%s", a[i], i == 2 ? "\n" : " ");
    return 0;
}
